/** کرنیل_قدر 안의 연결형 بائٹ_قدر بہاؤ_قدر. Ethernet/TCP 패킷 스택이 아닌 루프백 socket پرت_قدر. */
public final class بہاؤ_نیٹ_ورک {
    static int[] حالت_قدر = new int[16], پورٹ_قدر = new int[16], 짝 = new int[16], ساتھی_پورٹ = new int[16], انتظار_قدر = new int[16], 묶임 = new int[16];
    static int[] 앞 = new int[16], 수 = new int[16], کوائف = new int[16 * 1024];
    static int اگلا_شے = 50000;
    static int تصدیق_کریں(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && حالت_قدر[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int دہانہ_نمبر) { for (int لوپ_اشاریہ = 0; لوپ_اشاریہ < 16; لوپ_اشاریہ++) if (حالت_قدر[لوپ_اشاریہ] != 0 && 묶임[لوپ_اشاریہ] != 0 && پورٹ_قدر[لوپ_اشاریہ] == دہانہ_نمبر) return true; return false; }
    public static int بنائیں_اندراج() {
        for (int لوپ_اشاریہ = 0; لوپ_اشاریہ < 16; لوپ_اشاریہ++) if (حالت_قدر[لوپ_اشاریہ] == 0) { حالت_قدر[لوپ_اشاریہ] = 1; ساتھی_پورٹ[لوپ_اشاریہ] = پورٹ_قدر[لوپ_اشاریہ] = 앞[لوپ_اشاریہ] = 수[لوپ_اشاریہ] = انتظار_قدر[لوپ_اشاریہ] = 묶임[لوپ_اشاریہ] = 0; 짝[لوپ_اشاریہ] = -1; return لوپ_اشاریہ + 40; }
        return -24;
    }
    public static int 묶기(int 열린파일번호, int 통신주소, int دہانہ_نمبر) {
        int لوپ_اشاریہ = تصدیق_کریں(열린파일번호); if (لوپ_اشاریہ < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (حالت_قدر[لوپ_اشاریہ] != 1 || دہانہ_نمبر < 0 || دہانہ_نمبر > 65535) return -22;
        if (دہانہ_نمبر == 0) { do { دہانہ_نمبر = اگلا_شے++; if (اگلا_شے > 65535) اگلا_شے = 50000; } while (사용중(دہانہ_نمبر)); }
        if (사용중(دہانہ_نمبر)) return -98; پورٹ_قدر[لوپ_اشاریہ] = دہانہ_نمبر; 묶임[لوپ_اشاریہ] = 1; حالت_قدر[لوپ_اشاریہ] = 2; return 0;
    }
    public static int 듣기(int 열린파일번호, int 연결대기한도) { int لوپ_اشاریہ = تصدیق_کریں(열린파일번호); if (لوپ_اشاریہ < 0) return -9; if (حالت_قدر[لوپ_اشاریہ] != 2 || 연결대기한도 < 1) return -22; حالت_قدر[لوپ_اشاریہ] = 3; return 0; }
    public static int متصل_ہوں(int 열린파일번호, int 통신주소, int دہانہ_نمبر) {
        int لوپ_اشاریہ = تصدیق_کریں(열린파일번호); if (لوپ_اشاریہ < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (دہانہ_نمبر < 1 || دہانہ_نمبر > 65535 || حالت_قدر[لوپ_اشاریہ] > 2) return -22;
        int 수신쪽 = -1; for (int اندرونی_جوڑ_پوزیشن_ٹھیک_کریں = 0; اندرونی_جوڑ_پوزیشن_ٹھیک_کریں < 16; اندرونی_جوڑ_پوزیشن_ٹھیک_کریں++) if (حالت_قدر[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] == 3 && پورٹ_قدر[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] == دہانہ_نمبر) 수신쪽 = اندرونی_جوڑ_پوزیشن_ٹھیک_کریں;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int اندرونی_جوڑ_پوزیشن_ٹھیک_کریں = 0; اندرونی_جوڑ_پوزیشن_ٹھیک_کریں < 16; اندرونی_جوڑ_پوزیشن_ٹھیک_کریں++) if (انتظار_قدر[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (حالت_قدر[لوپ_اشاریہ] == 1) { int 처리값 = 묶기(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = بنائیں_اندراج(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        حالت_قدر[لوپ_اشاریہ] = حالت_قدر[다른번호] = 4; 짝[لوپ_اشاریہ] = 다른번호; 짝[다른번호] = لوپ_اشاریہ; پورٹ_قدر[다른번호] = دہانہ_نمبر; ساتھی_پورٹ[لوپ_اشاریہ] = دہانہ_نمبر; ساتھی_پورٹ[다른번호] = پورٹ_قدر[لوپ_اشاریہ]; انتظار_قدر[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int قبول_کریں_رابطہ(int 열린파일번호) { int لوپ_اشاریہ = تصدیق_کریں(열린파일번호); if (لوپ_اشاریہ < 0) return -9; if (حالت_قدر[لوپ_اشاریہ] != 3) return -22; for (int اندرونی_جوڑ_پوزیشن_ٹھیک_کریں = 0; اندرونی_جوڑ_پوزیشن_ٹھیک_کریں < 16; اندرونی_جوڑ_پوزیشن_ٹھیک_کریں++) if (حالت_قدر[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] != 0 && انتظار_قدر[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] == لوپ_اشاریہ + 1) { انتظار_قدر[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] = 0; return اندرونی_جوڑ_پوزیشن_ٹھیک_کریں + 40; } return -11; }
    public static int لکھیں(int 열린파일번호, int 항목수) {
        int لوپ_اشاریہ = تصدیق_کریں(열린파일번호); if (لوپ_اشاریہ < 0) return -9; if (حالت_قدر[لوپ_اشاریہ] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int اندرونی_جوڑ_پوزیشن_ٹھیک_کریں = 짝[لوپ_اشاریہ]; if (اندرونی_جوڑ_پوزیشن_ٹھیک_کریں < 0) return -32; int 총수 = 1024 - 수[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int 비교자리 = 0; 비교자리 < 총수; 비교자리++) کوائف[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں * 1024 + (앞[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] + 수[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] + 비교자리) % 1024] = 되돌림망.فارورڈ_قدر[비교자리]; 수[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] += 총수; return 총수;
    }
    public static int پڑھیں(int 열린파일번호, int 항목수) {
        int لوپ_اشاریہ = تصدیق_کریں(열린파일번호); if (لوپ_اشاریہ < 0) return -9; if (حالت_قدر[لوپ_اشاریہ] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[لوپ_اشاریہ] == 0) return 짝[لوپ_اشاریہ] < 0 ? 0 : -11; if (항목수 > 수[لوپ_اشاریہ]) 항목수 = 수[لوپ_اشاریہ];
        for (int 비교자리 = 0; 비교자리 < 항목수; 비교자리++) 되돌림망.فارورڈ_قدر[비교자리] = کوائف[لوپ_اشاریہ * 1024 + (앞[لوپ_اشاریہ] + 비교자리) % 1024]; 앞[لوپ_اشاریہ] = (앞[لوپ_اشاریہ] + 항목수) % 1024; 수[لوپ_اشاریہ] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int لوپ_اشاریہ = تصدیق_کریں(열린파일번호); return لوپ_اشاریہ < 0 ? -9 : پورٹ_قدر[لوپ_اشاریہ]; }
    public static int 상대창구읽기(int 열린파일번호) { int لوپ_اشاریہ = تصدیق_کریں(열린파일번호); return لوپ_اشاریہ < 0 ? -9 : ساتھی_پورٹ[لوپ_اشاریہ]; }
    public static int بند_کریں(int 열린파일번호) {
        int لوپ_اشاریہ = تصدیق_کریں(열린파일번호); if (لوپ_اشاریہ < 0) return -9;
        if (حالت_قدر[لوپ_اشاریہ] == 3) for (int اندرونی_جوڑ_پوزیشن_ٹھیک_کریں = 0; اندرونی_جوڑ_پوزیشن_ٹھیک_کریں < 16; اندرونی_جوڑ_پوزیشن_ٹھیک_کریں++) if (انتظار_قدر[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] == لوپ_اشاریہ + 1) { if (짝[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] >= 0) 짝[짝[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں]] = -1; حالت_قدر[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] = انتظار_قدر[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] = 묶임[اندرونی_جوڑ_پوزیشن_ٹھیک_کریں] = 0; }
        if (짝[لوپ_اشاریہ] >= 0) 짝[짝[لوپ_اشاریہ]] = -1; حالت_قدر[لوپ_اشاریہ] = 묶임[لوپ_اشاریہ] = 수[لوپ_اشاریہ] = انتظار_قدر[لوپ_اشاریہ] = 0; return 0;
    }
}
